import CoreGraphics
import XCTest
@testable import RockBreakerScissors

@MainActor
final class RockBreakerScissorsTests: XCTestCase {
    private func withModel(_ body: (GameViewModel, UserDefaults) -> Void) {
        let suite = "RockBreakerScissorsTests.\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        body(GameViewModel(defaults: defaults), defaults)
    }

    func testCampaignProgression() {
        let levels = LevelLibrary.allLevels
        XCTAssertEqual(levels.map(\.levelNumber), Array(1...100))
        for level in levels {
            XCTAssertGreaterThan(level.startingAmmo, 0)
            XCTAssertGreaterThan(level.launchSpeed, 0)
            XCTAssertFalse(level.initialObjects.isEmpty)
            for object in level.initialObjects {
                XCTAssertTrue((0...1).contains(object.xPercent))
                XCTAssertTrue((0...1).contains(object.yPercent))
                XCTAssertGreaterThan(object.radius, 0)
            }
        }
        for level in levels.dropFirst(5) {
            XCTAssertFalse(level.initialObjects.allSatisfy { $0.type == .scissors }, "Level \(level.levelNumber)")
        }
        XCTAssertTrue(levels.prefix(10).allSatisfy(\.isTutorial))
        XCTAssertTrue(levels.dropFirst(10).allSatisfy { !$0.isTutorial })
        XCTAssertTrue(levels.prefix(5).allSatisfy(\.allowsScissorsBeforeFirstShot))
        XCTAssertTrue(levels.dropFirst(5).allSatisfy { !$0.allowsScissorsBeforeFirstShot })
        for level in levels.prefix(3) {
            XCTAssertFalse(level.initialObjects.contains { $0.type == .paper })
        }
        for level in levels[10..<15] {
            XCTAssertLessThanOrEqual(level.launchSpeed, 120)
            XCTAssertLessThanOrEqual(level.initialObjects.count, 4)
            XCTAssertGreaterThanOrEqual(level.startingAmmo, 8)
            XCTAssertTrue(level.walls.isEmpty)
        }
        for level in levels[10..<35] {
            XCTAssertFalse(level.initialObjects.contains { $0.type == .rock })
        }
        for level in levels[10..<45] { XCTAssertTrue(level.walls.isEmpty) }
        for level in levels[10..<65] {
            for object in level.initialObjects where object.velocity.length > 0 {
                XCTAssertEqual(object.velocity.length, level.launchSpeed, accuracy: 0.001)
            }
        }
        for number in stride(from: 16, through: 96, by: 10) {
            XCTAssertNotNil(levels[number - 1].introMessage)
        }
        XCTAssertTrue(levels[35].initialObjects.contains { $0.type == .rock })
        XCTAssertFalse(levels[45].walls.isEmpty)
        XCTAssertTrue(levels[55].initialObjects.allSatisfy { $0.velocity.length == 0 })
    }

    func testSelectingEveryLessonShowsItsOwnTextWithExistingProgress() {
        withModel { model, defaults in
            model.highestUnlockedLevel = 100
            // Old completion flags must never suppress an explicitly selected lesson.
            defaults.set(31, forKey: "completedTutorialLevels")
            for index in 0..<10 {
                model.selectLevel(index)
                XCTAssertTrue(model.showTutorial)
                XCTAssertEqual(model.levelTitle, "Lesson \(index + 1)")
                XCTAssertEqual(model.currentTutorialMessage, model.tutorialMessages.first)
                while model.showTutorial { model.advanceTutorial() }
                model.restartLevel()
                XCTAssertFalse(model.showTutorial)
                model.showInstructions()
                XCTAssertEqual(model.currentTutorialMessage, model.tutorialMessages.first)
                model.goToMenu()
            }
            let reopened = GameViewModel(defaults: defaults)
            reopened.selectLevel(0)
            XCTAssertTrue(reopened.showTutorial)
            reopened.startGame(at: 99)
            XCTAssertEqual(reopened.levelTitle, "Level 100")
            XCTAssertEqual(reopened.currentTutorialMessage, LevelLibrary.level100.introMessage)
            XCTAssertFalse(reopened.currentTutorialMessage?.contains("Tap a target") ?? true)
        }
    }

    func testLessonMessagesRemainUntilAcknowledged() {
        withModel { model, _ in
            model.startGame(at: 0)
            let first = model.currentTutorialMessage
            XCTAssertTrue(model.showTutorial)
            XCTAssertEqual(model.currentTutorialMessage, first)
            model.advanceTutorial()
            XCTAssertTrue(model.showTutorial)
            XCTAssertNotEqual(model.currentTutorialMessage, first)
            model.advanceTutorial()
            XCTAssertFalse(model.showTutorial)
            model.restartLevel()
            XCTAssertFalse(model.showTutorial)
            model.showInstructions()
            model.skipTutorial()
            XCTAssertFalse(model.showTutorial)
        }
    }

    func testFinalLessonLeadsToFirstRegularLevel() {
        withModel { model, _ in
            model.highestUnlockedLevel = 10
            model.selectLevel(9)
            XCTAssertEqual(model.levelTitle, "Lesson 10")
            XCTAssertTrue(model.currentLevel.isTutorial)
            XCTAssertTrue(model.showTutorial)
            model.skipTutorial()
            model.completeLevel(finalObjectType: .rock)
            XCTAssertEqual(model.highestUnlockedLevel, 11)
            model.goToNextLevel()
            XCTAssertEqual(model.levelTitle, "Level 11")
            XCTAssertFalse(model.currentLevel.isTutorial)
            XCTAssertFalse(model.currentLevel.allowsScissorsBeforeFirstShot)
            XCTAssertTrue(model.showTutorial)
        }
    }

    func testContinueRemembersAcknowledgedLessonButSelectionCanReplayIt() {
        withModel { model, defaults in
            model.startGame(at: 0)
            model.skipTutorial()
            model.goToMenu()
            let reopened = GameViewModel(defaults: defaults)
            reopened.startGame(at: reopened.continueLevelIndex)
            XCTAssertFalse(reopened.showTutorial)
            reopened.selectLevel(0)
            XCTAssertTrue(reopened.showTutorial)
            reopened.skipTutorial()
            reopened.resetProgress()
            reopened.startGame(at: 0)
            XCTAssertTrue(reopened.showTutorial)
        }
    }

    func testCampaignCompletionAndRandomModeDoNotShareProgress() {
        withModel { model, defaults in
            model.highestUnlockedLevel = 100
            model.selectLevel(99)
            model.skipTutorial()
            model.completeLevel(finalObjectType: .rock)
            XCTAssertTrue(model.isCampaignVictory)
            XCTAssertTrue(model.campaignCompleted)
            XCTAssertTrue(GameViewModel(defaults: defaults).campaignCompleted)
            model.startRandomGame()
            XCTAssertTrue(model.isRandomMode)
            XCTAssertFalse(model.showTutorial)
            XCTAssertFalse(model.hasNextLevel)
            let original = model.currentLevel.initialObjects.map(\.xPercent)
            model.useAmmo()
            model.restartLevel()
            XCTAssertEqual(model.currentLevel.initialObjects.map(\.xPercent), original)
            XCTAssertEqual(model.ammoRemaining, model.currentLevel.startingAmmo)
            model.skipRandomLevel()
            XCTAssertEqual(model.randomRound, 2)
            model.completeLevel(finalObjectType: .rock)
            XCTAssertFalse(model.isCampaignVictory)
            XCTAssertEqual(model.highestUnlockedLevel, 100)
            model.selectLevel(0)
            XCTAssertFalse(model.isRandomMode)
            XCTAssertTrue(model.showTutorial)
            model.resetProgress()
            XCTAssertFalse(model.campaignCompleted)
            XCTAssertEqual(model.highestUnlockedLevel, 1)
        }
        withModel { model, _ in
            model.startRandomGame()
            model.completeLevel(finalObjectType: .rock)
            XCTAssertEqual(model.highestUnlockedLevel, 1)
            XCTAssertFalse(model.campaignCompleted)
            model.goToNextLevel()
            XCTAssertTrue(model.isRandomMode)
            XCTAssertEqual(model.randomRound, 2)
        }
    }

    func testRandomLayoutsHaveBothTypesAndNoStartupOverlaps() {
        var generator = SeededGenerator(state: 42)
        var counts = Set<Int>()
        var firstPositions = Set<CGFloat>()
        for _ in 0..<300 {
            let level = LevelLibrary.randomLevel(using: &generator)
            XCTAssertTrue((3...8).contains(level.initialObjects.count))
            XCTAssertTrue(level.initialObjects.contains { $0.type == .paper })
            XCTAssertTrue(level.initialObjects.contains { $0.type == .scissors })
            XCTAssertTrue(level.initialObjects.allSatisfy { (90...200.001).contains($0.velocity.length) })
            XCTAssertTrue(level.walls.isEmpty)
            counts.insert(level.initialObjects.count)
            firstPositions.insert(level.initialObjects[0].xPercent)
            assertClearLayout(level, size: CGSize(width: 320, height: 568))
        }
        XCTAssertEqual(counts.count, 6)
        XCTAssertGreaterThan(firstPositions.count, 250)
    }

    func testCampaignLayoutsDoNotStartOverlappingObjectsOrWalls() {
        for level in LevelLibrary.allLevels {
            for size in [CGSize(width: 320, height: 568), CGSize(width: 390, height: 600), CGSize(width: 768, height: 900)] {
                assertClearLayout(level, size: size)
            }
        }
    }

    private func assertClearLayout(_ level: LevelDefinition, size: CGSize) {
        let width = size.width - 48, height = size.height - 72
        for (i, object) in level.initialObjects.enumerated() {
            let point = CGPoint(x: 24 + object.xPercent * width, y: 48 + object.yPercent * height)
            let radius = object.radius * 0.8
            XCTAssertGreaterThanOrEqual(point.x - radius, 24)
            XCTAssertLessThanOrEqual(point.x + radius, size.width - 24)
            XCTAssertGreaterThanOrEqual(point.y - radius, 48)
            XCTAssertLessThanOrEqual(point.y + radius, size.height - 24)
            for other in level.initialObjects.dropFirst(i + 1) {
                let dx = (object.xPercent - other.xPercent) * width
                let dy = (object.yPercent - other.yPercent) * height
                XCTAssertGreaterThan(hypot(dx, dy), (object.radius + other.radius) * 0.8, "Level \(level.levelNumber)")
            }
            for wall in level.walls {
                let wallWidth = max(8, wall.widthPercent * width)
                let wallHeight = max(8, wall.heightPercent * height)
                let expanded = CGRect(x: 24 + wall.xPercent * width - wallWidth / 2,
                                      y: 48 + wall.yPercent * height - wallHeight / 2,
                                      width: wallWidth, height: wallHeight).insetBy(dx: -radius, dy: -radius)
                XCTAssertFalse(expanded.contains(point), "Level \(level.levelNumber) starts inside a wall")
            }
        }
    }

    func testTutorialPausesMovementAndFiring() {
        let scene = GameScene(size: CGSize(width: 320, height: 568))
        var shots = 0
        scene.didUseAmmo = { shots += 1 }
        scene.load(level: LevelLibrary.level3)
        let scissors = scene.children.filter { $0.name == "scissors" }
        let positions = scissors.map(\.position)
        scene.isGameplayPaused = true
        for frame in 0..<180 { scene.update(Double(frame) / 60) }
        scene.launchRock(toward: CGPoint(x: 160, y: 300))
        XCTAssertEqual(scissors.map(\.position), positions)
        XCTAssertEqual(shots, 0)
        scene.isGameplayPaused = false
        scene.launchRock(toward: CGPoint(x: 160, y: 300))
        XCTAssertEqual(shots, 1)
    }

    func testMixedRocksAndPaperDoesNotTriggerALoss() {
        let scene = GameScene(size: CGSize(width: 320, height: 568))
        let level = LevelDefinition(levelNumber: 0, startingAmmo: 8, launchSpeed: 100, launchedRockRadius: 20, initialObjects: [
            InitialObjectDefinition(type: .rock, xPercent: 0.3, yPercent: 0.5, angleDegrees: 0, speed: 0, radius: 20),
            InitialObjectDefinition(type: .paper, xPercent: 0.7, yPercent: 0.5, angleDegrees: 0, speed: 0, radius: 20)
        ])
        var lost = false
        scene.onLose = { _ in lost = true }
        scene.load(level: level)
        for frame in 0..<600 { scene.update(Double(frame) / 60) }
        XCTAssertFalse(lost)
    }

    func testScissorsOnlySetupIsSafeBeforeTheFirstShot() {
        let scene = GameScene(size: CGSize(width: 320, height: 568))
        var ammo = 1
        var lost = false
        scene.canLaunchRock = { ammo > 0 }
        scene.onLose = { _ in lost = true }
        scene.load(level: LevelLibrary.level1)
        scene.update(0)
        XCTAssertFalse(lost)
        ammo = 0
        scene.update(1.0 / 60)
        XCTAssertTrue(lost)
    }

    func testLaterLessonsRegularLevelsAndRandomRoundsLoseToAllScissorsBeforeFiring() {
        for number in [0, 6, 10, 11, 100] {
            let scene = GameScene(size: CGSize(width: 320, height: 568))
            var lostTo: ObjectType?
            scene.canLaunchRock = { true }
            scene.onLose = { lostTo = $0 }
            scene.load(level: LevelDefinition(levelNumber: number, startingAmmo: 8, launchSpeed: 100, launchedRockRadius: 20,
                                              initialObjects: LevelLibrary.level1.initialObjects))
            scene.update(0)
            XCTAssertEqual(lostTo, .scissors, "Level \(number) must lose before any shot")
        }
    }

    func testAllScissorsAfterFiringLosesEvenWithAmmoRemaining() {
        let scene = GameScene(size: CGSize(width: 320, height: 568))
        var ammo = 8
        var lostTo: ObjectType?
        scene.canLaunchRock = { ammo > 0 }
        scene.didUseAmmo = { ammo -= 1 }
        scene.onLose = { lostTo = $0 }
        scene.load(level: LevelDefinition(levelNumber: 0, startingAmmo: 8, launchSpeed: 100, launchedRockRadius: 20, initialObjects: [
            InitialObjectDefinition(type: .paper, xPercent: 0.5, yPercent: 0.08, angleDegrees: 0, speed: 0, radius: 20),
            InitialObjectDefinition(type: .scissors, xPercent: 0.5, yPercent: 0.4, angleDegrees: 0, speed: 0, radius: 20)
        ]))
        scene.launchRock(toward: CGPoint(x: 160, y: 500))
        for frame in 0..<1800 {
            scene.update(Double(frame) / 60)
            if lostTo != nil { break }
        }
        XCTAssertEqual(lostTo, .scissors)
        XCTAssertEqual(ammo, 7)
    }

    func testEveryCampaignLevelHasARecordedWinningSequence() {
        // Generated from level-audit.csv. Replay against the real SpriteKit scene,
        // including fully stationary puzzles solved by rock -> paper -> scissors.
        let cases = campaignWinningSequences.split(separator: "\n")
        XCTAssertEqual(cases.count, 300)
        for line in cases {
            autoreleasepool {
                let fields = line.split(separator: ",", omittingEmptySubsequences: false)
                let number = Int(fields[0])!
                let width = CGFloat(Double(fields[1])!), height = CGFloat(Double(fields[2])!)
                let level = LevelLibrary.allLevels[number - 1]
                let scene = GameScene(size: CGSize(width: width, height: height))
                var ammo = level.startingAmmo
                var won = false, lost = false
                scene.canLaunchRock = { ammo > 0 }
                scene.didUseAmmo = { ammo -= 1 }
                scene.onWin = { _ in won = true }
                scene.onLose = { _ in lost = true }
                scene.load(level: level)
                let shots = fields[3].split(separator: ";").map { $0.split(separator: ":") }
                var nextShot = 0
                for frame in 0..<7200 {
                    if nextShot < shots.count, Int(shots[nextShot][0]) == frame {
                        let shot = shots[nextShot]
                        scene.launchRock(toward: CGPoint(x: width * CGFloat(Double(shot[1])!), y: height * CGFloat(Double(shot[2])!)))
                        nextShot += 1
                    }
                    scene.update(Double(frame) / 60)
                    if won || lost { break }
                }
                XCTAssertTrue(won, "Level \(number), \(width)x\(height)")
                XCTAssertFalse(lost)
                XCTAssertGreaterThanOrEqual(ammo, 0)
            }
        }
    }
}

private struct SeededGenerator: RandomNumberGenerator {
    var state: UInt64
    mutating func next() -> UInt64 {
        state = state &* 6364136223846793005 &+ 1442695040888963407
        return state
    }
}

